// ============================================================
// SAFETY NET - Verificación summary <-> close_conversation
//
// Regla: si el Agente envía 【summary:...】 TIENE que haber
// ejecutado close_conversation, y si ejecutó close_conversation
// TIENE que haber enviado el summary. Si falta uno de los dos
// -> force_recovery.
//
// El tag 【alert:close_conversation】 queda deprecado: ya no se
// usa para decidir nada y, si aparece, se elimina del output.
//
// Guarda anti-loop: $runIndex es el nº de corrida de ESTE nodo
// dentro de la ejecución. Se permiten hasta MAX_RETRIES reintentos;
// si el Agente sigue inconsistente, se deja pasar para no entrar
// en un bucle infinito.
// ============================================================
const agentOutput = $input.first().json;
let outputText = agentOutput.output || '';
const steps = agentOutput.intermediateSteps || [];

const MAX_RETRIES = 2;
const canRetry = $runIndex < MAX_RETRIES;

// ------------------------------------------------------------
// Limpieza: alert tag deprecado (por si el modelo lo sigue mandando)
// ------------------------------------------------------------
outputText = outputText
  .replace(/【alert:\s*"?close_conversation"?】/gi, '')
  .trim();

// ------------------------------------------------------------
// Largo máximo: WhatsApp (Twilio) rechaza mensajes de más de
// 1600 caracteres (error 21617) y el cliente no recibe nada.
// Los tags 【...】 no se envían como texto, así que no cuentan.
// ------------------------------------------------------------
const MAX_CHARS = 1500;
const CIERRE_RECORTE = '\n\n¿Querés que te amplíe alguna versión en particular? 😊';
const recortar = (txt) => {
  const tags = txt.match(/【[^】]*】/g) || [];
  const texto = txt.replace(/【[^】]*】/g, '').trim();
  if (texto.length <= MAX_CHARS) return txt;
  const limite = MAX_CHARS - CIERRE_RECORTE.length;
  const corte = texto.lastIndexOf('\n', limite);
  const recorte = texto.slice(0, corte > limite / 2 ? corte : limite).trim();
  return [recorte + CIERRE_RECORTE, ...tags].join('\n');
};
outputText = recortar(outputText);

// ------------------------------------------------------------
// Estado: ¿hay summary? ¿se ejecutó close_conversation?
// ------------------------------------------------------------
const SUMMARY_TAG_REGEX = /【summary:/i;
const hasSummary = SUMMARY_TAG_REGEX.test(outputText);

const closeStep = steps.find(s =>
  s.action?.tool?.toLowerCase().startsWith('close_conversation')
);
const closeCalled = !!closeStep;

const recovery = (reason) => [{
  json: {
    action: 'force_recovery',
    reason,
    output: outputText,
    intermediateSteps: steps
  }
}];

const passthrough = (extra = {}) => [{
  json: {
    action: 'passthrough',
    ...extra,
    output: outputText,
    intermediateSteps: steps
  }
}];

// ============================================================
// CAPA 1: Consistencia summary <-> close_conversation
// ============================================================

// summary SIN close_conversation
if (hasSummary && !closeCalled && canRetry) {
  return recovery('summary_sin_close_conversation');
}

// close_conversation SIN summary
if (closeCalled && !hasSummary && canRetry) {
  return recovery('close_conversation_sin_summary');
}

// ============================================================
// CAPA 2: Ambos presentes -> inyectar `user` en el summary
// ============================================================
if (hasSummary && closeCalled) {
  try {
    let obs = closeStep.observation;
    if (obs && typeof obs === 'object') obs = JSON.stringify(obs);
    obs = String(obs || '');
    const m = obs.match(/"welcome_assigned_user_email"\s*:\s*"([^"]+)"/i);
    const email = m && m[1] ? m[1].trim() : '';

    if (email) {
      outputText = outputText.replace(
        /(【summary:\s*)(\{[\s\S]*?\})(\s*】)/i,
        (full, pre, jsonStr, post) => {
          try {
            const obj = JSON.parse(jsonStr);
            obj.user = email;
            return pre + JSON.stringify(obj) + post;
          } catch (e) {
            return full;
          }
        }
      );
    }
  } catch (e) {
    // no-op: si algo falla, se deja el summary tal cual
  }
  return passthrough();
}

// Reintentos agotados con uno de los dos faltando -> dejar pasar
if (hasSummary || closeCalled) {
  return passthrough({
    reason: hasSummary
      ? 'retries_agotados_summary_sin_close_conversation'
      : 'retries_agotados_close_conversation_sin_summary'
  });
}

// ============================================================
// CAPA 3: Ni summary ni tool -> chequeo de palabras de despedida
// Si parece despedida/derivación pero no hubo cierre formal,
// se manda a verificación LLM.
// ============================================================
const FAREWELL_KEYWORDS = /asesor|contactar[áa]|nos comunicamos|te vamos a contactar|un representante|en breve|a la brevedad|hasta luego|hasta pronto|fue un placer|cualquier consulta|no dudes en|chau|bye|suerte/i;

if (!FAREWELL_KEYWORDS.test(outputText)) {
  return passthrough();
}

return [{
  json: {
    action: 'needs_llm_verification',
    output: outputText,
    intermediateSteps: steps
  }
}];

